/** Stub shape — fields beyond identity are validated when a provider implements it. */
interface ProjectBoard {
    id: string;
    rawData: unknown;
}
/** Stub shape — fields beyond identity are validated when a provider implements it. */
interface Milestone {
    id: string;
    rawData: unknown;
}
